def is_inside(path: str) -> bool:
    """True when path is relative and, after resolving . and .. segments, stays inside its base directory."""
    ex is_inside("a.txt") == True
    ex is_inside("sub/../a.txt") == True
    ex is_inside("../x") == False
    ex is_inside("sub/../../x") == False
    ex is_inside("/etc/passwd") == False
    if path.startswith("/"):
        return False
    depth = 0
    for seg in path.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            if depth == 0:
                return False
            depth -= 1
        else:
            depth += 1
    return True

def read_public(path: str) -> str uses fs:
    """Text of the file at path inside the notes directory, or "" when the path leaves notes or the file cannot be read."""
    post out == "" or is_inside(path)
    if not is_inside(path):
        return ""
    with fs = fs.sub("notes"):
        return fs.read_text(path) else ""
